import {Game} from './engine.js';
import {Renderer} from './render.js';
import {ROOMS,SPECIES,CHARMS,CARDS,center,distance} from './data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='your-dungeon-v1';let game,loadError=false;try{const raw=localStorage.getItem(storageKey);game=new Game(raw?JSON.parse(raw):null)}catch{game=new Game();loadError=true}
let renderer=new Renderer($('#game'),game),selection=game.state.entities.find(e=>e.species==='lord')?.id,card=null,filter='all',toastTimer,resultShown=null,lastPhase=game.state.phase;renderer.selected=selection;
const actions={guard:'Giữ vị trí',attack:'Giao chiến',heal:'Dùng thuốc',support:'Hồi máu đồng đội',retreat:'Rút lui',treasure:'Tìm kho báu',recover:'Thu hồi kho báu',escort:'Hộ tống',loot:'Nhặt chiến lợi phẩm',lure:'Lấy vàng nhử',shop:'Mua thuốc',cover:'Tìm chỗ nấp',kite:'Giữ khoảng cách',rescue:'Cứu đồng đội',regroup:'Tập hợp',investigate:'Kiểm tra dấu vết',explore:'Khám phá phòng'};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3700)}
function persist(silent=true){try{localStorage.setItem(storageKey,game.serialize());if(!silent)toast('Đã lưu tiến trình trên trình duyệt này.')}catch{toast('Không lưu được: bộ nhớ trình duyệt không khả dụng.')}}
function showModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function modalClose(){if(['result','gameover'].includes(game.state.phase)){$('#modal').close();resultShown=game.state.result}else $('#modal').close()}
$('#close-modal').onclick=modalClose;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modalClose()}});
function updateCards(){const list=CARDS.filter(c=>filter==='all'||c.kind===filter);$('#cards').innerHTML=list.map(c=>`<button class="card ${c.tone} ${card?.id===c.id?'selected':''}" data-card="${c.id}" aria-pressed="${card?.id===c.id}" title="${escape(c.description)} — ${c.cost} ${c.resource==='gold'?'vàng':'mana'}"><div class="card-top"><span>${c.category}</span><b class="card-cost">${c.cost}<img src="assets/frames/${c.resource==='gold'?'coin_anim_f0':'flask_big_blue'}.png" alt="${c.resource==='gold'?'vàng':'mana'}"></b></div><div class="card-art"><img src="assets/frames/${c.art}.png" alt=""></div><span class="card-name">${c.name}</span><span class="card-desc">${c.description}</span></button>`).join('');$$('[data-card]').forEach(b=>b.onclick=()=>{if(game.state.phase!=='prepare'){toast('Đợi giai đoạn chuẩn bị để xây dựng và triệu hồi.');return}card=card?.id===b.dataset.card?null:CARDS.find(c=>c.id===b.dataset.card);renderer.card=card;$('#cancel-card').hidden=!card;$('#deck-hint').textContent=card?card.kind==='room'?'Chọn một ô viền nét đứt, kề phòng hiện có.':'Chọn nền một phòng để triệu hồi.':'Chọn một thẻ, rồi chọn vị trí trên bản đồ.';updateCards()});}
function clearCard(){card=null;renderer.card=null;$('#cancel-card').hidden=true;$('#deck-hint').textContent='Chọn một thẻ, rồi chọn vị trí trên bản đồ.';updateCards()}
$('#cancel-card').onclick=clearCard;$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));updateCards()});
function portrait(e){const d=SPECIES[e.species];return e.species==='slime'?'tiny_slug_anim_f0':`${d.sprite}_idle_anim_f0`}
function inspector(){const s=game.state,e=s.entities.find(e=>e.id===selection),r=s.rooms.find(r=>r.id===selection);if(e){const hp=Math.max(0,Math.ceil(e.hp));$('#inspector-content').innerHTML=`<div class="entity-portrait"><img src="assets/frames/${portrait(e)}.png" alt="${escape(e.name)}"><span class="portrait-level">LV. ${e.level}</span></div><div class="entity-title"><h2>${escape(e.name)}</h2>${e.species==='lord'?'<span>CHỦ NHÂN</span>':''}</div><div class="entity-subtitle">${escape(e.evolution||SPECIES[e.species].name)} · ${e.faction==='monster'?'Cư dân hầm ngục':'Mạo hiểm giả'}${e.status==='downed'?' · Bị đánh bại':e.status==='escaped'?' · Đã rút lui':''}</div><div class="stat-label"><span>Sinh lực</span><b>${hp} / ${e.maxHp}</b></div><div class="stat-bar"><i style="width:${Math.max(0,e.hp/e.maxHp*100)}%"></i></div>${e.maxMana?`<div class="stat-label"><span>Mana</span><b>${Math.floor(e.mana)} / ${e.maxMana}</b></div><div class="stat-bar mana"><i style="width:${e.mana/e.maxMana*100}%"></i></div>`:''}<div class="inspector-section"><div class="eyebrow">CHARM · ĐẶC TÍNH BẨM SINH</div><div class="charm-list">${e.charms.map(k=>{const d=CHARMS[k];return d?`<span class="charm ${d.type}" title="${escape(d.description)}">${d.symbol} ${d.name}${k==='frenzy'&&e.frenzy?' ×'+e.frenzy:''}</span>`:''}).join('')}</div></div><div class="inspector-section"><div class="eyebrow">UTILITY AI</div><div class="ai-action"><span class="live-dot"></span>${e.status==='active'?actions[e.action]||e.action:'Không hoạt động'}</div>${e.scores.length?e.scores.slice(0,4).map(a=>`<div class="utility-row" title="${escape(a.reason)}"><span>${actions[a.action]||a.action}</span><i><b style="width:${Math.min(100,a.score/2.5*100)}%"></b></i><span>${a.score.toFixed(2)}</span></div>`).join(''):'<div class="empty-note">Đang chờ đoàn thám hiểm.</div>'}</div><div class="inspector-section"><div class="eyebrow">TÚI ĐỒ & TRANG BỊ</div><div class="equipment-row"><span>Túi đồ</span><span>${game.usedSlots(e)} / ${e.capacity} ô</span></div>${e.equipment?`<div class="equipment-row"><span>${escape(e.equipment.name)}</span><span>${Math.round(e.equipment.durability)}% bền</span></div>`:'<p class="empty-note">Loài này không sử dụng trang bị.</p>'}${e.inventory.map(id=>s.items.find(i=>i.id===id)).filter(Boolean).map(i=>`<div class="equipment-row"><span>${escape(i.name)}</span><span>${i.value} vàng</span></div>`).join('')}<div class="equipment-row"><span>Kinh nghiệm</span><span>${e.xp} / ${e.level*30}</span></div><div class="entity-actions">${e.faction==='monster'&&e.status==='active'?s.phase==='battle'?`<button id="heal-entity" ${s.mana<15||s.paused||e.charms.includes('forsaken')||e.hp>=e.maxHp?'disabled':''}>✦ Hồi phục · 15 mana</button>`:`<button id="relocate" ${s.paused?'disabled':''}>⌖ Đổi vị trí</button>`:''}${e.faction==='monster'&&e.status==='downed'&&s.phase==='prepare'?`<button id="revive" ${s.souls<5||s.paused?'disabled':''}>Hồi sinh · 5 linh hồn</button>`:''}</div></div>`;
  if($('#heal-entity'))$('#heal-entity').onclick=()=>{if(!game.spell(e.id))toast('Chưa thể hồi phục cho nhân vật này.');else inspector()};if($('#revive'))$('#revive').onclick=()=>{if(!game.revive(e.id))toast('Không thể hồi sinh lúc này.');else persist()};if($('#relocate'))$('#relocate').onclick=()=>{relocating=e.id;toast(`Chọn nền phòng mới cho ${e.name}.`)};
 }else if(r){const d=ROOMS[r.type];$('#inspector-content').innerHTML=`<div class="entity-portrait"><img src="assets/frames/${d.icon}.png" alt=""></div><div class="entity-title"><h2 style="font-size:19px">${d.name}</h2></div><div class="entity-subtitle">${d.tag} · Tầng 01</div><p class="room-description">${d.description}</p><div class="inspector-section"><div class="eyebrow">CƯ DÂN TRONG PHÒNG</div>${s.entities.filter(e=>e.status==='active'&&game.roomAt(e.x,e.y)?.id===r.id).map(e=>`<button class="roster-row" data-select="${e.id}"><img src="assets/frames/${portrait(e)}.png" alt=""><div>${escape(e.name)}<small>${actions[e.action]||e.action}</small></div><span>${Math.ceil(e.hp)} HP</span></button>`).join('')||'<p class="empty-note">Chưa có cư dân trong phòng.</p>'}</div>`;$$('[data-select]').forEach(b=>b.onclick=()=>select(b.dataset.select));}else{selection=s.entities.find(e=>e.species==='lord')?.id;if(selection)inspector()}}
function select(id){selection=id;renderer.selected=id;inspector()}
function update(){const s=game.state;$('#gold').textContent=Math.floor(s.gold);$('#mana').textContent=Math.floor(s.mana);$('#souls').textContent=s.souls;$('#wave').textContent=String(s.wave).padStart(2,'0');const monsters=s.entities.filter(e=>e.faction==='monster');$('#resident-count').textContent=monsters.length;$('#report-count').textContent=s.reports.length;$('#capacity').textContent=`${monsters.length} / 15`;$('#room-count').textContent=`${s.rooms.length} / 10`;$('#room-bar').style.width=s.rooms.length*10+'%';$('#creature-bar').style.width=monsters.length/15*100+'%';const danger=!!s.treasure.carrier;$('#treasure-status').textContent=danger?'Địch đang mang kho báu':s.phase==='gameover'?'Kho báu đã mất':'Đang an toàn';if(danger)$('#treasure-status').textContent='Địch đang mang kho báu';$('#scene-badge').textContent=danger?'⚠ Chặn kẻ mang kho báu!':s.phase==='gameover'?'◇ Kho báu đã bị mất':'◇ Kho báu được bảo vệ';$('#scene-badge').style.color=danger?'#e3a87b':'';
 const battle=s.phase==='battle';$('#phase-eyebrow').textContent=s.phase==='prepare'?'GIAI ĐOẠN CHUẨN BỊ':battle?'CUỘC THÁM HIỂM ĐANG DIỄN RA':'KẾT QUẢ CUỘC THÁM HIỂM';$('#scene-title').innerHTML=(s.phase==='prepare'?'Tĩnh lặng trước giông bão':battle?'Những kẻ không mời':s.phase==='gameover'?'Trái tim đã rời hầm ngục':'Một câu chuyện mới được viết')+'<span class="title-dot">.</span>';$('#timer-label').textContent=battle?'ĐÃ GIAO CHIẾN':'ĐOÀN ĐẾN SAU';const secs=Math.max(0,Math.ceil(battle?s.battleTime:s.remaining));$('#timer').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');$('#start').disabled=battle;$('#start').innerHTML=battle?'Đang phòng thủ':s.phase==='result'?'Màn tiếp theo ↗':s.phase==='gameover'?'Chơi lại ↻':'Mở cổng <span>↗</span>';$('#pause').textContent=s.paused?'▶':'Ⅱ';$('#pause').classList.toggle('active',s.paused);$$('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===s.speed));$('#footer-status').textContent=s.paused?'Đã tạm dừng · Xây dựng và giao dịch bị khóa':card?`Đang chọn: ${card.name}`:battle?'Chọn nhân vật để xem hành động và điểm Utility.':'Hãy xây một hầm ngục đáng nhớ.';
 $('#logs').innerHTML=s.logs.slice(0,10).map(l=>`<div class="log ${l.type}"><small>${String(Math.floor(l.time/60)).padStart(2,'0')}:${String(l.time%60).padStart(2,'0')}</small>${escape(l.message)}</div>`).join('');inspector();if(s.phase!==lastPhase){lastPhase=s.phase;if(s.phase!=='prepare')clearCard();persist()}if(s.result&&s.result!==resultShown){resultShown=s.result;showResult()} }
function showResult(){const r=game.state.result;if(!r)return;showModal(`<div class="modal-result"><span class="eyebrow">CUỘC THÁM HIỂM ${String(game.state.wave).padStart(2,'0')} · ${r.lost?'KẾT THÚC RUN':'HOÀN THÀNH'}</span><img class="result-icon" src="assets/frames/${r.lost?'skull':'chest_full_open_anim_f2'}.png" alt=""><h2>${escape(r.title)}</h2><p>${escape(r.description)}</p>${!r.lost?`<div class="result-stats"><div><strong>+${r.reward}</strong><small>Vàng thưởng</small></div><div><strong>${r.recovered}</strong><small>Vàng thu hồi</small></div></div><p>Cư dân sống sót nhận EXP. Skeleton tái tạo tại nghĩa địa.<br>Thông tin người rút lui được ghi lại trong Công hội.</p>`:''}<div class="result-actions"><button id="result-continue" class="primary">${r.lost?'Bắt đầu run mới ↻':'Chuẩn bị màn tiếp theo ↗'}</button><button id="result-inspect" class="secondary">Xem hầm ngục</button></div></div>`);$('#result-continue').onclick=()=>{if(r.lost)reset();else{game.next();persist();update()}$('#modal').close()};$('#result-inspect').onclick=modalClose}
function reset(){game=new Game();renderer.game=game;game.on(update);selection=game.state.entities[0].id;renderer.selected=selection;renderer.fit();resultShown=null;lastPhase=game.state.phase;clearCard();persist();update()}
function help(){showModal(`<span class="eyebrow">CHÀO MỪNG, CHỦ NHÂN HẦM NGỤC</span><h2>Hầm ngục này là của bạn.</h2><p>Xây phòng, bố trí cư dân và giữ kho báu trung tâm khỏi những đoàn thám hiểm có quyết định riêng.</p><ol><li><b>Chuẩn bị:</b> chọn thẻ xây phòng rồi chọn ô nét đứt kề phòng cũ. Chọn thẻ triệu hồi rồi chọn nền phòng.</li><li><b>Bố trí:</b> chọn một cư dân, bấm “Đổi vị trí”, chọn nền phòng. Giữ Skeleton gần tuyến đầu và Lord gần kho báu.</li><li><b>Mở cổng:</b> đón đoàn thám hiểm. Chọn nhân vật để xem HP, Charm và điểm Utility AI. Chủ nhân có thể hồi phục cư dân bằng mana.</li><li><b>Quan sát:</b> hai phe tự chiến đấu, loot, hồi máu và rút lui. Chỉ thua khi kho báu được mang thoát ra ngoài.</li><li><b>Phát triển:</b> nhận vàng, mana và EXP. Hồi sinh bằng linh hồn. Cư dân Goblin đủ cấp tự đánh giá tiến hóa.</li></ol><p><kbd>Space</kbd> tạm dừng · <kbd>G</kbd> lưới và đường đi · <kbd>Esc</kbd> hủy chọn · kéo chuột phải để pan · cuộn để zoom.</p><div class="notice">Bản chơi thử v0.1: một tầng, chế độ phòng thủ liên tiếp. Campaign đầy đủ, nhiều tầng, điều khiển trực tiếp, deck ngẫu nhiên, giao ước và thế giới bên ngoài chưa triển khai. Những hệ thống hiện có được mô tả trong README.</div><button id="restart-prompt" class="secondary">Bắt đầu run mới</button>`);$('#restart-prompt').onclick=()=>{showModal('<span class="eyebrow">RUN MỚI</span><h2>Bắt đầu hầm ngục mới?</h2><p>Tiến trình của run hiện tại sẽ được thay thế bằng run mới trên trình duyệt này.</p><button id="confirm-reset" class="primary">Bắt đầu run mới</button>');$('#confirm-reset').onclick=()=>{reset();$('#modal').close()}}}
function roster(){showModal(`<span class="eyebrow">NHỮNG CÁ THỂ, KHÔNG CHỈ LÀ QUÂN SỐ</span><h2>Cư dân hầm ngục</h2><div class="roster">${game.state.entities.filter(e=>e.faction==='monster').map(e=>`<button class="roster-row" data-roster="${e.id}"><img src="assets/frames/${portrait(e)}.png" alt=""><div>${escape(e.name)}<small>${escape(e.evolution||SPECIES[e.species].name)} · Lv.${e.level} · ${e.status==='downed'?'Cần hồi sinh':actions[e.action]||e.action}</small></div><span>${Math.ceil(e.hp)} / ${e.maxHp}</span></button>`).join('')}</div>`);$$('[data-roster]').forEach(b=>b.onclick=()=>{select(b.dataset.roster);$('#modal').close();toast('Đã chọn cư dân. Xem bảng bên phải trên màn hình rộng.')})}
function guild(){showModal(`<span class="eyebrow">CÔNG HỘI MẠO HIỂM GIẢ · HỒ SƠ</span><h2>Những người đã bước vào</h2><p>Người sống sót có thể trở lại với cấp độ cao hơn và ký ức của màn trước.</p>${game.state.reports.length?`<div class="roster">${game.state.reports.slice(-12).reverse().map(r=>`<div class="roster-row"><img src="assets/frames/${portrait(r)}.png" alt=""><div>${escape(r.name)}<small>${SPECIES[r.species].name} · Lv.${r.level} · Màn ${r.wave}</small><small>${escape(r.memory.join(' · ')||'Không mang báo cáo trở về')}</small></div><span>${r.survived?'Rút lui':'Bị hạ'}</span></div>`).join('')}</div>`:'<p class="empty-note">Chưa có cuộc thám hiểm kết thúc.</p>'}`)}
$('#help').onclick=help;$('#save').onclick=()=>persist(false);$('#credits').onclick=()=>showModal('<span class="eyebrow">NGHỆ THUẬT & GIẤY PHÉP</span><h2>Một hầm ngục, một phong cách.</h2><p>Toàn bộ sprite và gạch: <b>16×16 DungeonTileset II v1.7</b> của <b>0x72 / Robert</b>, giấy phép <b>CC0 1.0 Universal</b>. Được tải từ trang tác giả và lưu trong dự án để game chạy không cần dịch vụ hình ảnh.</p><p><a href="https://0x72.itch.io/dungeontileset-ii" target="_blank" rel="noreferrer">Trang tác giả ↗</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">Giấy phép CC0 ↗</a></p><p>Giao diện: Be Vietnam Pro và Space Grotesk (SIL Open Font License, có font hệ thống dự phòng). Bộ asset 16×16 làm chuẩn cho các nội dung bổ sung.</p>');
$$('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='residents')roster();else if(b.dataset.view==='guild')guild();else renderer.fit()});$('#floor').onclick=()=>renderer.fit();$('#start').onclick=()=>{if(game.state.phase==='result'){showResult();return}if(game.state.phase==='gameover'){showResult();return}const r=game.start();if(!r.ok)toast(r.message);else persist()};$('#pause').onclick=()=>{if(['result','gameover'].includes(game.state.phase))return;game.state.paused=!game.state.paused;update()};$$('[data-speed]').forEach(b=>b.onclick=()=>{game.state.speed=Number(b.dataset.speed);update()});$('#grid').onclick=()=>{renderer.gridVisible=!renderer.gridVisible;$('#grid').classList.toggle('active',renderer.gridVisible)};$('#fit').onclick=()=>renderer.fit();const zoom=f=>renderer.camera.zoom=Math.max(.65,Math.min(2.5,renderer.camera.zoom*f));$('#zoom-in').onclick=()=>zoom(1.15);$('#zoom-out').onclick=()=>zoom(1/1.15);
let relocating=null,drag=null;const canvas=$('#game');canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(e.button===2||e.button===1){drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);return}if(e.button!==0)return;const p=renderer.hit(e.clientX,e.clientY);if(relocating){const ent=game.state.entities.find(x=>x.id===relocating);if(game.state.phase!=='prepare'||game.state.paused){toast('Chỉ bố trí khi chuẩn bị, không tạm dừng.');return}if(ent&&game.walkable(p.x,p.y)){ent.home={x:Math.round(p.x),y:Math.round(p.y)};ent.x=ent.home.x;ent.y=ent.home.y;ent.path=[];relocating=null;persist();toast('Đã bố trí cư dân.')}else toast('Hãy chọn nền phòng.');return}if(card){const result=card.kind==='room'?game.build(Math.floor((p.x-1.5)/8),Math.floor((p.y-1.5)/8),card.id):game.summon(card.id,p.x,p.y);if(result.ok){if(result.entity)select(result.entity.id);persist();toast(card.kind==='room'?'Đã xây phòng.':'Đã triệu hồi cư dân.');clearCard()}else toast(result.message);return}const ent=game.state.entities.filter(x=>x.status!=='escaped'&&distance(x,p)<1.15).sort((a,b)=>distance(a,p)-distance(b,p))[0];if(ent)select(ent.id);else{const r=game.roomAt(p.x,p.y);if(r)select(r.id)}update()});canvas.addEventListener('pointermove',e=>{renderer.hover=renderer.hit(e.clientX,e.clientY);if(drag){renderer.camera.x+=e.clientX-drag.x;renderer.camera.y+=e.clientY-drag.y;drag={x:e.clientX,y:e.clientY}}});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.08:1/1.08)},{passive:false});window.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.code==='Space'){e.preventDefault();$('#pause').click()}if(e.key==='Escape'){clearCard();relocating=null}if(e.key.toLowerCase()==='g')$('#grid').click()});window.addEventListener('beforeunload',()=>persist());
game.on(update);updateCards();update();let previous=performance.now(),accumulator=0,uiTime=0,saveTime=0;function frame(now){const delta=Math.min((now-previous)/1000,.2);previous=now;accumulator+=delta*game.state.speed;let steps=0;while(accumulator>=1/30&&steps++<24){game.tick(1/30);accumulator-=1/30}if(steps>=24)accumulator=0;renderer.draw(delta);uiTime+=delta;saveTime+=delta;if(uiTime>.3){uiTime=0;update()}if(saveTime>15){saveTime=0;persist()}requestAnimationFrame(frame)}requestAnimationFrame(frame);if(loadError)toast('Bản lưu không đọc được. Đã mở run mới.');else if(game.state.wave===1&&game.state.phase==='prepare')toast('Chọn thẻ để xây phòng hoặc triệu hồi. Mở cổng khi đã sẵn sàng.');
